          ...CartVariantFragment
          __typename
        }
        quantity
        __typename
      }
      productVariant {
        ...CartVariantFragment
        lowStockAmount
        product {
          salesData {
            approximateQuantitySoldLast30Days
            __typename
          }
          __typename
        }
        bundledBy {
          nodes {
            ...CartVariantFragment
            product {
              ...BundleProduct
              __typename
            }
            __typename
          }
          pageInfo {
            hasNextPage
            __typename
          }
          __typename
        }
        __typename
      }
      warnings {
        ...CartWarningFragment
        __typename
      }
      discountAllocations {
        ...DiscountAllocations
        __typename
      }
      __typename
