fragment OrderDeliveryMutation on Order {
  id
  uuid
  canUndoMarkAsDelivered
  displayStatus
  deliveryStatus
  markedAsDelivered
  markedAsDeliveredAt
  etaInfo {
    formattedEta
    formattedEtaTime
    isFuture
    __typename
  }
  deliveries {
    nodes {
      id
      status
      deliveredAt
      deliveryMethodType
      deliveryFlags
      etaInfo {
        formattedEtaDateAndTime
        __typename
      }
      # Mark/undo can create or remove a delivery. Keep the fields required to
