      tracker {
        id
        trackingCode
        trackingUrl
        carrierInfo {
          id
          name
          imageUrl
          __typename
        }
        __typename
      }
      events(last: 1) {
        nodes {
          ... on TrackerDeliveryEvent {
            happenedAt
            message
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

